#include "TextureDocument.hh"
#include <cassert>
#include <cmath>
#include <iostream>
int main(){using namespace bts;
  SceneSnapshot scene;MaterialSummary material;material.session_id=1;material.name="Cube";material.uniform_editable=true;scene.materials={material};ImportSummary imported;imported.materials={{1,"Cube"}};TextureDocument doc({},imported,scene);auto &set=doc.set(1);TextureDocument::add_fill(set);const auto bottom=set.selected_layer;TextureDocument::layer(set,bottom).values.roughness=.3;TextureDocument::add_fill(set);const auto top=set.selected_layer;
  const std::array<LayerBlend,16> modes{LayerBlend::Divide,LayerBlend::InverseDivide,LayerBlend::Darken,LayerBlend::Lighten,LayerBlend::LinearDodge,LayerBlend::Subtract,LayerBlend::InverseSubtract,LayerBlend::Difference,LayerBlend::Exclusion,LayerBlend::SignedAddition,LayerBlend::Overlay,LayerBlend::SoftLight,LayerBlend::HardLight,LayerBlend::VividLight,LayerBlend::LinearLight,LayerBlend::PinLight};
  const std::array<int,16> painter_bytes{153,255,77,128,205,0,51,51,128,78,115,108,166,153,204,127};
  for(int i=0;i<int(modes.size());++i){auto &upper=TextureDocument::layer(set,top);upper.values.roughness=i<10?.5f:.75f;upper.blending[2]=modes[i];const auto output=TextureDocument::evaluate(set).material;const int byte=int(std::round(precision_channel(output,2,set.precision[2])[0]*255));if(byte!=painter_bytes[i])std::cerr<<layer_blend_names[int(modes[i])]<<" got "<<byte<<" expected "<<painter_bytes[i]<<'\n';assert(byte==painter_bytes[i]);assert(TextureDocument::layer(set,bottom).values.roughness==.3f&&upper.values.roughness==(i<10?.5f:.75f));}
  for(int y=0;y<=256;++y)for(int x=0;x<=256;++x){const float a=x/256.f,b=y/256.f;assert(std::abs(blend_value(LayerBlend::Overlay,a,b)-blend_value(LayerBlend::HardLight,b,a))<1e-6);assert(std::abs(blend_value(LayerBlend::Difference,a,b)-blend_value(LayerBlend::Difference,b,a))<1e-7);for(auto mode:modes)assert(std::isfinite(blend_value(mode,a,b)));for(auto mode:{LayerBlend::Overlay,LayerBlend::SoftLight,LayerBlend::HardLight,LayerBlend::VividLight,LayerBlend::LinearLight,LayerBlend::PinLight})assert(std::abs(blend_value(mode,.5,b)-b)<1e-6);}
  const std::array<float,3> source{.2,.8,.3},backdrop{.7,.2,.4};const auto s=blend_rgb_to_hsv(source),b=blend_rgb_to_hsv(backdrop);
  for(auto mode:{LayerBlend::Tint,LayerBlend::Saturation,LayerBlend::Color,LayerBlend::Value}){const auto rgb=blend_rgb(mode,source,backdrop),hsv=blend_rgb_to_hsv(rgb);const bool hue_top=mode==LayerBlend::Tint||mode==LayerBlend::Color,sat_top=mode==LayerBlend::Saturation||mode==LayerBlend::Color;assert(std::abs(hsv[0]-(hue_top?s[0]:b[0]))<1e-6&&std::abs(hsv[1]-(sat_top?s[1]:b[1]))<1e-6&&std::abs(hsv[2]-(mode==LayerBlend::Value?s[2]:b[2]))<1e-6);}
  assert(blend_rgb(LayerBlend::Tint,{0,0,0},backdrop)==backdrop);assert(blend_rgb(LayerBlend::Tint,{.5,.5,.5},backdrop)==backdrop);for(int i=0;i<=360;++i){const std::array<float,3> hsv{float(i)/360,.8,.7};const auto roundtrip=blend_rgb_to_hsv(blend_hsv_to_rgb(hsv));const float hue_error=std::abs(roundtrip[0]-(hsv[0]-std::floor(hsv[0])));assert(std::min(hue_error,1-hue_error)<1e-6&&std::abs(roundtrip[1]-.8)<1e-6&&std::abs(roundtrip[2]-.7)<1e-6);}
  std::vector<TextureSetBinding> bindings{{set.id,1,set.name}};for(int mode=0;mode<int(layer_blend_names.size());++mode){TextureDocument::layer(set,top).blending.fill(LayerBlend(mode));const auto data=doc.to_json();assert(TextureDocument::from_json(data,bindings).to_json()==data);}
  std::cout<<"16 Painter scalar byte witnesses, 257x257 branch/identity matrix, saturated HSV components, achromatic fallback, hue wrap and all-mode serialization passed\n";
}
